<template><div class="login-page"><div class="login-card"><h2>{{ t('resetPasswordTitle') }}</h2><form class="login-form" @submit.prevent="submit"><div class="login-field"><label>{{ t('emailLabel') }}</label><input v-model="email" type="email" :placeholder="t('emailPlaceholder')" :disabled="codeSent" required /></div><template v-if="codeSent"><div class="login-field"><label>{{ t('emailVerificationCode') }}</label><input v-model="code" type="text" inputmode="numeric" maxlength="6" :placeholder="t('emailCodePlaceholder')" required /></div><div class="login-field"><label>{{ t('newPassword') }}</label><input v-model="password" type="password" :placeholder="t('newPasswordPlaceholder')" required /></div><div class="login-field"><label>{{ t('confirmNewPassword') }}</label><input v-model="confirmPassword" type="password" :placeholder="t('confirmPasswordPlaceholder')" required /></div></template><div v-if="error" class="login-error">{{ error }}</div><div v-if="message" class="login-success">{{ message }}</div><button class="login-submit" type="submit" :disabled="loading">{{ loading ? t('submitting') : codeSent ? t('confirmReset') : t('sendResetCode') }}</button></form><div class="login-switch"><RouterLink to="/login">{{ t('goLogin') }}</RouterLink></div></div></div></template>
<script setup>
import { ref } from 'vue'; import { useLang } from '../contexts/app'; import { authService } from '../services/authService'; import './LoginPage.css'
const {t}=useLang();const email=ref(''),code=ref(''),password=ref(''),confirmPassword=ref(''),codeSent=ref(false),error=ref(''),message=ref(''),loading=ref(false);const submit=async()=>{error.value='';message.value='';loading.value=true;try{if(!codeSent.value){const data=await authService.forgotPassword(email.value);codeSent.value=true;message.value=data.detail||t('resetCodeSent')}else{if(password.value.length<4){error.value=t('passwordMinLength');return}if(password.value!==confirmPassword.value){error.value=t('passwordMismatch');return}const data=await authService.resetPassword(email.value,code.value,password.value);message.value=data.detail||t('passwordResetSuccess');code.value='';password.value='';confirmPassword.value=''}}catch(e){error.value=e.response?.data?.detail||t('passwordResetFailed')}finally{loading.value=false}}
</script>
